import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const API = 'http://localhost:8080';

function base64urlToBuffer(value) {
  const base64 = value.replace(/-/g, '+').replace(/_/g, '/');
  const padded = base64.padEnd(
    Math.ceil(base64.length / 4) * 4,
    '='
  );

  const binary = atob(padded);

  return Uint8Array.from(binary, char => char.charCodeAt(0));
}

function Login() {
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async () => {
    try {
      setLoading(true);
      setMessage('Preparing passkey authentication...');

      if (!window.PublicKeyCredential) {
        throw new Error('Your browser does not support WebAuthn.');
      }

      // Step 1: Get CSRF token
      const csrfResponse = await fetch(`${API}/api/csrf`, {
        credentials: 'include'
      });

      if (!csrfResponse.ok) {
        throw new Error('Unable to obtain CSRF token.');
      }

      const csrf = await csrfResponse.json();

      // Step 2: Get authentication options
      const optionsResponse = await fetch(
        `${API}/webauthn/authenticate/options`,
        {
          method: 'POST',
          credentials: 'include',
          headers: {
            'X-CSRF-TOKEN': csrf.token
          }
        }
      );

      if (!optionsResponse.ok) {
        throw new Error('Unable to get authentication options.');
      }

      const options = await optionsResponse.json();

      // Decode binary values
      options.challenge = base64urlToBuffer(options.challenge);

      if (options.allowCredentials) {
        options.allowCredentials = options.allowCredentials.map(item => ({
          ...item,
          id: base64urlToBuffer(item.id)
        }));
      }

      setMessage('Please verify using your passkey...');

      // Step 3: Ask authenticator to authenticate
      const credential = await navigator.credentials.get({
        publicKey: options
      });

      if (!credential) {
        throw new Error('Passkey authentication was cancelled.');
      }

      // Step 4: Send assertion to Spring Boot
      const loginResponse = await fetch(`${API}/login/webauthn`, {
        method: 'POST',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-TOKEN': csrf.token
        },
        body: JSON.stringify(credential.toJSON())
      });

      if (!loginResponse.ok) {
        throw new Error('Passkey authentication failed.');
      }

      const result = await loginResponse.json();

      if (result.authenticated) {
        setMessage('Login successful!');
        navigate('/user-dashboard');
      } else {
        throw new Error('Authentication was not confirmed.');
      }

    } catch (error) {
      console.error(error);
      setMessage(error.message || 'Login failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mt-5">
      <div className="row justify-content-center">
        <div className="col-md-5">
          <div className="card shadow p-4">
            <h2 className="text-center mb-4">Passkey Login</h2>

            <p className="text-center text-muted">
              Authenticate securely using your registered passkey.
            </p>

            <button
              className="btn btn-primary w-100 mt-3"
              onClick={handleLogin}
              disabled={loading}
            >
              {loading ? 'Authenticating...' : 'Login with Passkey'}
            </button>

            {message && (
              <div className="alert alert-info mt-3">
                {message}
              </div>
            )}

            <p className="text-center mt-3">
              <Link to="/">Back to Home</Link>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Login;
